/**
 * LabLoggerAudio — short feedback cues for the Lab Logger.
 *
 * Owns:   one AudioComponent per cue (LowLatency — they react to input / logging).
 * Inputs: four AudioTrackAssets (generated by /build-sfx) + a volume.
 * API:    playStart(), playStop(), playRowLogged(), playNav()
 * Must not: decide when cues fire — LabLoggerMain calls these.
 */
@component
export class LabLoggerAudio extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">LabLoggerAudio – feedback sounds</span>')
  @ui.separator
  @ui.label('<span style="color: #60A5FA;">References</span>')
  @ui.group_start("References")
  @input
  @hint("Played when recording starts.")
  recordStartClip: AudioTrackAsset

  @input
  @hint("Played when recording stops.")
  recordStopClip: AudioTrackAsset

  @input
  @hint("Soft tick played each time a row is logged.")
  rowLoggedClip: AudioTrackAsset

  @input
  @hint("Played when Previous / Next is pressed on the graphs panel.")
  navClickClip: AudioTrackAsset
  @ui.group_end

  @ui.separator
  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Volume of all Lab Logger cues (0 = muted).")
  @widget(new SliderWidget(0, 1, 0.05))
  volume: number = 0.8
  @ui.group_end

  private players: AudioComponent[] = []

  onAwake(): void {
    for (const clip of [this.recordStartClip, this.recordStopClip, this.rowLoggedClip, this.navClickClip]) {
      const ac = this.sceneObject.createComponent("Component.AudioComponent") as AudioComponent
      if (clip) ac.audioTrack = clip
      ac.playbackMode = Audio.PlaybackMode.LowLatency
      ac.volume = this.volume
      this.players.push(ac)
    }
  }

  playStart(): void { this.play(0) }
  playStop(): void { this.play(1) }
  playRowLogged(): void { this.play(2) }
  playNav(): void { this.play(3) }

  private play(i: number): void {
    const ac = this.players[i]
    if (!ac || !ac.audioTrack || this.volume <= 0) return
    ac.volume = this.volume
    if (ac.isPlaying()) ac.stop(false)
    ac.play(1)
  }
}
